// patch applier
function apply(base, patch) {
  for (const k of Object.keys(patch)) {
    if (k === '__proto__') continue;
    if (patch[k] && typeof patch[k] === 'object') {
      base[k] = base[k] || {};
      apply(base[k], patch[k]);
    } else {
      base[k] = patch[k];
    }
  }
  return base;
}
